import React from "react";
import { fireEvent, render, screen } from "@testing-library/react";
import mediaQuery, { MediaValues } from "css-mediaquery";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import ConsoleSpy from "../../lib/tests/ConsoleSpy";
import * as stories from "./Select.stories";
import Select from ".";

const createMatchMedia = (hover: string) => (query: string) => ({
  matches: mediaQuery.match(query, { hover } as Partial<MediaValues>),
  addListener: () => {},
  removeListener: () => {},
});

const { Basic } = composeStories(stories) as any;

describe("Select component", () => {
  ConsoleSpy();

  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("passes through props to the input element", () => {
    render(
      <Select options={[{ label: "Bar", value: "foo" }]} data-testid="select" />
    );
    expect(screen.queryByRole("combobox")).toHaveAttribute(
      "data-testid",
      "select"
    );
  });

  it("allow forwardRef", () => {
    const SelectWithRef = () => {
      const selectRef = React.useRef<HTMLSelectElement>(null);
      React.useEffect(() => {
        selectRef.current && selectRef.current.focus();
      }, []);
      return <Select ref={selectRef} />;
    };

    render(<SelectWithRef />);
    expect(screen.getByRole("combobox")).toHaveFocus();
  });

  it("allow to choose from native to custom modes", () => {
    const consoleWarnSpy = jest.spyOn(console, "warn").mockImplementation(() => {});

    const options = [{ label: "Bar", value: "foo" }];
    const { rerender } = render(<Select options={options} />);
    expect(
      screen.queryByRole("button", { name: /toggle menu/ })
    ).not.toBeInTheDocument();
    expect(consoleWarnSpy).toHaveBeenCalledTimes(1);

    rerender(<Select options={options} mode="CUSTOM" />);
    expect(
      screen.getByRole("button", { name: /toggle menu/ })
    ).toBeInTheDocument();

    // @ts-ignore
    window.matchMedia = createMatchMedia("hover");
    rerender(<Select options={options} mode="AUTO" />);
    expect(
      screen.getByRole("button", { name: /toggle menu/ })
    ).toBeInTheDocument();

    // @ts-ignore
    window.matchMedia = createMatchMedia("none");
    rerender(<Select options={options} mode="AUTO" />);
    expect(
      screen.queryByRole("button", { name: /toggle menu/ })
    ).not.toBeInTheDocument();
    expect(consoleWarnSpy).toHaveBeenCalledTimes(3);

    consoleWarnSpy.mockRestore();
  });

  it("dispatch programmatic event in custom mode", () => {
    const onChange = jest.fn();
    const options = [{ label: "Bar", value: "foo" }];
    render(<Select options={options} mode="CUSTOM" onChange={onChange} />);

    fireEvent.click(screen.getByRole("button", { name: /toggle menu/ }));
    fireEvent.click(screen.getByRole("option", { name: "Bar" }));
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenCalledWith(expect.anything(), "foo");
    // check that mocked combobox onChange event transmits target.value correctly
    expect(onChange.mock.calls[0][0].target.value).toEqual("foo");
  });

  it("handle disabled attribute with custom mode #1401", () => {
    const options = [{ label: "Bar", value: "foo" }];
    render(<Select options={options} mode="CUSTOM" disabled />);
    expect(
      screen.queryByRole("button", { name: /toggle menu/ })
    ).toBeDisabled();
    expect(screen.queryByRole("combobox")).toBeDisabled();
  });

  it("readonly input in custom mode", () => {
    const options = [{ label: "Bar", value: "foo" }];
    render(<Select options={options} mode="CUSTOM" />);
    expect(screen.getByRole("combobox")).toHaveAttribute("readonly");
  });

  it("allow grouping options", () => {
    const options = [{ label: "Bar", value: "foo" }, { label: "Foo", value: "bar" }];
    render(<Select options={options} mode="NATIVE" groupBy={(option) => option.value.charAt(0)} />);
    expect(screen.getAllByRole("group")).toHaveLength(2);
  })
});
